#include "AiEsp32RotaryEncoder.h"

extern AiEsp32RotaryEncoder rotaryEncoder;

// define some events that can be generated by the encoder
// These can be translated by the application if wanted to eg lv events
typedef enum {
    ROT_NONE,
    ROT_UP,     // value is increasing
    ROT_DOWN,   // decreasing
    ROT_CLICK,  // Button pushed
    ROT_MAX,
}RotaryEV;

RotaryEV rotary_loop();
void rotary_setup();
long rotary_getvalue();